  lesson_id uuid not null, content_blocks jsonb not null,
  backed_up_at timestamptz not null default now(), note text);
alter table lesson_content_backup enable row level security;

insert into lesson_content_backup (lesson_id, content_blocks, note)
select id, content_blocks, 'before content rewrite (c_cysa_d1, c_cysa_d2, c_cysa_d3, c_cysa_d4)' from lessons where id in ('2b8b3720-a83c-40f6-b406-952cf72a71f5', '62400032-1d81-4dc3-8782-1ae726061ef3', '85906821-5f25-4d58-96ca-62012be7bb8c', '35ae6282-d734-4570-9460-ce42715d1c20', '4574b25e-8f4b-466a-8501-4d7451e1bcc5', '94e69121-55e1-48e5-89ab-94ec90f4cb58', '12cc49be-1646-4e27-b09f-e3390949c5c5', '04c36d74-68ee-40e3-9dec-d3b7575b2af0', 'ce2b8f00-78d0-4575-bf80-5005c62d5e4f', 'b36dd07e-ef33-4c64-916a-83f37388ab91', '3fb82ba8-b37d-480a-bad4-3db813b8d6b0', 'e5559adc-ffb8-47c5-81e1-7241c00dce1e', '26a384cf-3a9c-4a77-97f6-daedfdb13d18', 'c24220d0-7952-4f04-8b91-4bd12f9cc046', '260e6761-06bb-459a-920e-30fce991f28c', 'b0d864aa-3d42-422b-ae6a-9189b1ca72fd', 'bb79bdac-6e4c-433f-a4a4-8a1addf702d4', '239e9727-aa93-47ce-a11c-8147f2e26788', '3353e8d3-70c2-4dc8-94d7-d3bf52b8c154', '2847cc69-38f5-40c9-80a7-94757e3d4306', '645f3c7c-9787-4319-ad03-3a4f9c34d596', '2a9bc0d8-2567-4a94-a181-3d2330a38eff', 'b665931f-217f-4c9c-885f-412f569d76d3', 'bbe7b6c9-8716-4a60-b2e8-8410ec12465f', 'a3e0ced0-64ed-4c09-94fb-cf8e23935ce1', 'fb2d8d41-db4d-450c-b64a-3fa458f4a48b', '8104720e-83f5-44f1-a2b9-58b17c0483a2', 'e83210fd-971f-493a-879a-985d35696139', '06ac9b03-2165-4aae-bd4b-9bde86b5bf2d', '863553b6-99dd-406c-82f5-7d317ee6347f', '2a38db67-3145-4ed5-bf86-39693d7b06fe', '399ec20d-c5f2-4ebe-8907-02d8bcf5a9e8', 'e0f19da0-6f19-43e8-90c8-80ef3ca23897', 'e649db35-ed6c-4afd-816a-fd405ea65612', '98d933ab-59dc-4db2-8fee-fedb93c7bf4b', '320f3220-7ba3-484a-886b-2056a6d36373', 'a2f17b46-0b93-4611-bdac-cfffc81d6b91')
  and not exists (select 1 from lesson_content_backup b where b.lesson_id = lessons.id and b.note = 'before content rewrite (c_cysa_d1, c_cysa_d2, c_cysa_d3, c_cysa_d4)');

-- What the CySA+ Exam Actually Tests
update lessons set content_blocks = '[{"text": "What the CySA+ Exam Actually Tests", "type": "title", "overview": "A map of the four domains covered in this course, and how CompTIA actually scores the current CS0-004 exam.", "examContext": "Why this matters: domain weights tell you where to put your study time before you spend a single hour on content."}, {"type": "paragraph", "text": "CySA+ is CompTIA''s intermediate certification for SOC analysts, incident responders and threat hunters. It sits between Security+ and advanced credentials like CISSP, and it''s heavy on hands-on detection, analysis and response."}, {"type": "term_set", "heading": "The exam at a glance", "terms": [{"term": "Exam", "short": "CompTIA CySA+ CS0-004, which replaced CS0-003."}, {"term": "Length", "short": "85 questions in 165 minutes."}, {"term": "Question types", "short": "Multiple choice plus performance-based questions."}, {"term": "Passing score", "short": "750 on a 100 to 900 scale."}, {"term": "Recommended experience", "short": "About four years of hands-on security work."}]}, {"type": "compare", "heading": "The four domains and their weight", "columns": ["Weight"], "rows": [{"label": "1. Security Operations", "values": ["34%, the largest"]}, {"label": "2. Vulnerability Management", "values": ["26%"]}, {"label": "3. Incident Response and Management", "values": ["24%"]}, {"label": "4. Reporting and Communication", "values": ["16%"]}]}, {"type": "callout", "variant": "info", "text": "CS0-004 added a new objective on **AI in security operations**. Older study material won''t mention it, so don''t skip it here."}, {"type": "callout", "variant": "tip", "text": "Security Operations and Vulnerability Management together are 60% of your score."}]'::jsonb where id = '2b8b3720-a83c-40f6-b406-952cf72a71f5';

-- How to Use Orivian
update lessons set content_blocks = '[{"text": "How to Use Orivian", "type": "title", "overview": "How a domain''s lessons, recap, and checkpoint fit together, and what it takes to mark a lesson complete.", "examContext": "Why this matters: understanding the platform''s rhythm up front means you spend your time studying, not figuring out the interface."}, {"type": "paragraph", "text": "Every domain in this course follows the same pattern. Learn it once and you know it everywhere."}, {"type": "diagram", "heading": "Inside a domain", "diagram": {"kind": "flow", "steps": [{"label": "Lessons", "note": "Each lesson ends in a 10-question mini-exam. 80% to pass; retake as often as you like."}, {"label": "Domain recap", "note": "The highest-yield facts from every lesson, plus rapid practice questions. No exam."}, {"label": "Domain checkpoint", "note": "A longer exam across the whole domain, with fresh scenarios. The real test of whether it stuck."}]}}, {"type": "term_set", "heading": "How a lesson is laid out", "terms": [{"term": "Key terms at a glance", "short": "Every term with a one-line definition, often next to a diagram."}, {"term": "Breakdown", "short": "Terms in depth, each with an \"In practice\" example."}, {"term": "Side by side", "short": "Comparison tables for the pairs the exam loves, with an exam cue row."}, {"term": "How this shows up on the exam", "short": "Practice questions: pick an answer, then see why it''s right and what the trap was. Not scored."}, {"term": "Mini-exam", "short": "The graded questions at the end. You can review every past attempt afterwards."}]}, {"type": "term_set", "heading": "Finding your way", "terms": [{"term": "The trail map", "short": "Each course page shows your path as a trail: covered ground in green, your next waypoint in gold."}, {"term": "Next waypoint", "short": "The card at the top of the course page always points to your next step."}, {"term": "Study timer", "short": "Counts only while a lesson or exam is visible in front of you. For your awareness; never graded."}, {"term": "Listen", "short": "Any slide can be read aloud. Turn on auto-play in Voice settings to hear each slide as you press Next."}, {"term": "Keyboard", "short": "Arrow keys move between slides, L listens, N opens notes."}]}, {"type": "term_set", "heading": "Your notes", "terms": [{"term": "Write a note", "short": "Open Notes in any lesson and type; it''s linked to that lesson automatically."}, {"term": "Save to notes", "short": "Select any sentence in a lesson and tap Save to notes to keep it as a quote."}, {"term": "My Notes", "short": "Everything you''ve saved, on the Notes page, grouped by course and lesson."}], "intro": "Notes are private to you and follow your account to any device."}, {"type": "callout", "variant": "tip", "text": "One or two lessons done attentively beat a skimmed marathon. Use the recap right before the checkpoint."}]'::jsonb where id = '62400032-1d81-4dc3-8782-1ae726061ef3';

-- A Study Strategy That Works
update lessons set content_blocks = '[{"text": "A Study Strategy That Works", "type": "title", "overview": "A short, practical approach to pacing your study time and building the scenario-analysis skill CySA+ actually tests.", "examContext": "Why this matters: CySA+ leans heavily on ''given a scenario'' questions rather than pure definition recall, it tests judgment under realistic conditions, not just vocabulary."}, {"type": "paragraph", "text": "CySA+ rarely asks what a term means. It hands you a log excerpt, a scan result or an incident timeline and asks what you''d do next."}, {"type": "term_set", "heading": "How to study", "terms": [{"term": "Read indicators, not just names", "short": "The exam describes traffic and expects you to recognize beaconing in it."}, {"term": "Use frameworks as tools", "short": "Kill Chain, Diamond Model and ATT&CK are lenses for analyzing a described attack."}, {"term": "Don''t skip Reporting and Communication", "short": "Only 16%, but it''s often under-studied and costs real points."}]}, {"type": "diagram", "heading": "The order behind \"what''s the next step?\"", "diagram": {"kind": "flow", "steps": [{"label": "Preparation"}, {"label": "Detection and analysis"}, {"label": "Containment"}, {"label": "Eradication"}, {"label": "Recovery"}, {"label": "Post-incident"}]}, "caption": "Many CySA+ questions test whether you''d skip ahead in this order."}, {"type": "scenario", "prompt": "An analyst confirms malware on a laptop that is actively beaconing out. What''s the best **next** step?", "choices": [{"id": "a", "text": "Reimage the laptop immediately"}, {"id": "b", "text": "Isolate the laptop from the network"}, {"id": "c", "text": "Write the lessons learned report"}, {"id": "d", "text": "Restore files from backup"}], "answer": "b", "why": "With the incident confirmed, containment comes next: stop it spreading and talking to its controller.", "trap": "Reimaging and restoring belong to eradication and recovery. Jumping there first can destroy evidence and skip scoping."}, {"type": "callout", "variant": "tip", "text": "For \"best next step\" questions, locate where the scenario is in the response order, then pick the step that comes right after."}]'::jsonb where id = '85906821-5f25-4d58-96ca-62012be7bb8c';

-- System and Network Architecture Fundamentals
update lessons set content_blocks = '[{"text": "System and Network Architecture Fundamentals", "type": "title", "overview": "The architectural building blocks a SOC analyst needs to understand before interpreting any alert: logging, OS hardening, and modern infrastructure patterns.", "examContext": "Expect scenario questions where recognizing the underlying architecture changes what the ''correct'' investigative step is."}, {"type": "term_set", "heading": "Key terms at a glance", "terms": [{"term": "Logging", "short": "The foundation of every investigation."}, {"term": "Time synchronization", "short": "NTP across all systems so timelines line up."}, {"term": "Logging level", "short": "Verbosity: too low misses evidence, too high drowns in noise."}, {"term": "OS hardening", "short": "Fewer services and accounts, least privilege, patched."}]}, {"type": "key_term", "term": "Logging level", "definition": "Debug, info, warning, error, critical. The setting decides what evidence will exist later.", "example": "Authentication logging was set to errors only, so successful logins by the attacker were never recorded."}, {"type": "compare", "heading": "Where evidence lives", "columns": ["Virtual machine", "Container", "Serverless"], "rows": [{"label": "What it is", "values": ["A full OS on a hypervisor", "An app and its dependencies sharing the host kernel", "Short-lived functions run by the provider"]}, {"label": "Can you image it?", "values": ["Yes, snapshot the VM", "Sometimes, if still running", "No persistent host at all"]}, {"label": "Main evidence", "values": ["Disk, memory, logs", "Image, runtime logs, host logs", "Invocation logs and telemetry only"]}]}, {"type": "scenario", "prompt": "A serverless function was abused to exfiltrate data. Where will the investigator find evidence?", "choices": [{"id": "a", "text": "A disk image of the server"}, {"id": "b", "text": "Logs and telemetry captured when the function ran"}, {"id": "c", "text": "The function''s RAM dump"}, {"id": "d", "text": "The hypervisor''s snapshot"}], "answer": "b", "why": "Serverless has no persistent host; invocation logging is the only evidence."}, {"type": "scenario", "prompt": "Logs from the firewall, domain controller and web server can''t be lined up into a single timeline. What most likely went wrong?", "choices": [{"id": "a", "text": "Logging level too high"}, {"id": "b", "text": "Clocks aren''t synchronized"}, {"id": "c", "text": "Too many log sources"}, {"id": "d", "text": "OS hardening"}], "answer": "b", "why": "Without NTP, timestamps disagree and correlation fails."}, {"type": "callout", "variant": "tip", "text": "No time sync, no timeline. Serverless means logging at run time is all you''ll ever get."}]'::jsonb where id = '35ae6282-d734-4570-9460-ce42715d1c20';

-- Identity, Encryption, and Modern Network Architecture
update lessons set content_blocks = '[{"text": "Identity, Encryption, and Modern Network Architecture", "type": "title", "overview": "How identity, encryption, and network architecture combine to control who can reach what, and how that control has shifted away from a hardened network perimeter.", "examContext": "Expect questions asking you to recognize a Zero Trust or SASE control described in a scenario, and to distinguish encryption types by where the data is at the time."}, {"type": "term_set", "heading": "Key terms at a glance", "terms": [{"term": "IAM", "short": "The right people and systems get the right access, and no more."}, {"term": "Least privilege", "short": "Only the access needed, nothing extra \"just in case\"."}, {"term": "Zero trust", "short": "Never trust, always verify; every request authenticated and validated."}, {"term": "SASE", "short": "Networking and security delivered together from the cloud."}, {"term": "Hybrid cloud", "short": "On premises plus cloud providers, monitored consistently."}]}, {"type": "key_term", "term": "SASE", "definition": "Secure access service edge combines SD-WAN with zero trust access, secure web gateway, CASB and firewall as a service in one cloud platform.", "example": "A remote employee''s traffic goes to the nearest SASE point of presence for inspection, instead of back through headquarters."}, {"type": "compare", "heading": "Encryption by data state", "columns": ["At rest", "In transit", "In use"], "rows": [{"label": "Protects", "values": ["Stored data", "Data crossing a network", "Data being processed in memory"]}, {"label": "Example", "values": ["Disk and database encryption", "TLS, IPsec", "Confidential computing"]}]}, {"type": "scenario", "prompt": "Security policies follow remote users wherever they work, enforced from the cloud rather than a central data center. What is this?", "choices": [{"id": "a", "text": "VPN concentrator"}, {"id": "b", "text": "SASE"}, {"id": "c", "text": "Hybrid cloud"}, {"id": "d", "text": "DMZ"}], "answer": "b", "why": "Cloud-delivered security that follows the user is SASE."}, {"type": "scenario", "prompt": "A user on the corporate LAN must reauthenticate and pass a device health check to open a sensitive app. Which model?", "choices": [{"id": "a", "text": "Perimeter security"}, {"id": "b", "text": "Zero trust"}, {"id": "c", "text": "Least privilege only"}, {"id": "d", "text": "Defense in depth only"}], "answer": "b", "why": "Being inside the network earns nothing; every request is verified."}, {"type": "callout", "variant": "tip", "text": "SASE is how zero trust reaches a remote workforce. Match encryption to the data''s state."}]'::jsonb where id = '4574b25e-8f4b-466a-8501-4d7451e1bcc5';

-- Recognizing Network and Host Indicators of Malicious Activity
update lessons set content_blocks = '[{"text": "Recognizing Network and Host Indicators of Malicious Activity", "type": "title", "overview": "The specific network and host-level signs that separate normal activity from an attack in progress.", "examContext": "CySA+ frequently describes a symptom (unexpected ports, a spike in CPU, an odd process) and asks you to name the indicator category, practice recognizing behavior, not memorizing a glossary."}, {"type": "compare", "heading": "Network vs. host indicators", "columns": ["Network", "Host"], "rows": [{"label": "Examples", "values": ["Rogue devices, scanning, unexpected open ports, beaconing", "Resource spikes, suspicious processes, unauthorized changes"]}, {"label": "Seen in", "values": ["Traffic, flow data, firewall logs", "EDR, process lists, registry, task scheduler"]}]}, {"type": "key_term", "term": "Beaconing", "definition": "Regular, periodic outbound connections to an external host. A classic sign of command and control.", "example": "A workstation contacts the same unfamiliar domain every 60 seconds, around the clock, with tiny payloads."}, {"type": "key_term", "term": "LOLBin", "definition": "A legitimate, built-in binary abused by an attacker, such as PowerShell, certutil or wmic. It''s trusted and signed, so signatures miss it.", "example": "certutil -urlcache is used to download a payload, because certutil is a normal Windows tool."}, {"type": "term_set", "heading": "Host indicators", "terms": [{"term": "Abnormal resource use", "short": "Unexplained CPU, memory or disk spikes; cryptominers are a common cause."}, {"term": "Suspicious processes", "short": "Unknown names, odd parents, running from temp folders."}, {"term": "Unauthorized changes", "short": "New scheduled tasks, run keys or services with no change record."}]}, {"type": "scenario", "prompt": "EDR shows WINWORD.EXE spawning powershell.exe with an encoded command. What does this most likely indicate?", "choices": [{"id": "a", "text": "A normal Office update"}, {"id": "b", "text": "Malicious macro execution"}, {"id": "c", "text": "Beaconing"}, {"id": "d", "text": "Scanning"}], "answer": "b", "why": "An Office document launching a shell is one of the highest-yield indicators on the exam."}, {"type": "scenario", "prompt": "A server''s CPU sits at 100% overnight with no scheduled jobs, and it connects to a mining pool. Which indicator category is this?", "choices": [{"id": "a", "text": "Network: rogue device"}, {"id": "b", "text": "Host: abnormal resource consumption"}, {"id": "c", "text": "Identity: impossible travel"}, {"id": "d", "text": "Application anomaly"}], "answer": "b", "why": "Unexplained resource use on the host, a typical cryptominer sign."}, {"type": "callout", "variant": "tip", "text": "Office spawning a shell means a malicious macro. Regular outbound calls to the same host means beaconing."}]'::jsonb where id = '94e69121-55e1-48e5-89ab-94ec90f4cb58';

-- Application, Cloud, and Identity-Based Indicators
update lessons set content_blocks = '[{"text": "Application, Cloud, and Identity-Based Indicators", "type": "title", "overview": "Indicators that show up outside the network/host layer, in applications, cloud environments, identity systems, and social engineering attempts.", "examContext": "These indicator types are increasingly common on the exam as more attacks target cloud identity rather than on-premises infrastructure directly."}, {"type": "term_set", "heading": "Application and cloud anomalies", "terms": [{"term": "Application", "short": "Unusual error rates or API calls; an app touching data it never used before."}, {"term": "Cloud", "short": "Unfamiliar API calls, resources in unused regions, buckets suddenly made public."}]}, {"type": "key_term", "term": "Impossible travel", "definition": "One account authenticates from two places too far apart to travel between in the time elapsed. A strong sign of stolen credentials.", "example": "A login from Dallas at 9:02 and another from Bucharest at 9:20, both for the same user."}, {"type": "term_set", "heading": "Identity indicators", "terms": [{"term": "Impossible travel", "short": "Geographically impossible logins."}, {"term": "Failed login spikes", "short": "Password spraying or brute force."}, {"term": "Unfamiliar device or time", "short": "Logins outside the user''s pattern."}, {"term": "Unticketed privilege escalation", "short": "New admin rights with no change record."}]}, {"type": "key_term", "term": "Business email compromise (BEC)", "definition": "An attacker impersonates or takes over an executive''s mailbox to request a payment or data. Usually no malware at all.", "example": "\"The CFO\" emails accounts payable from finance-corp.co asking for an urgent, confidential wire before the end of the day."}, {"type": "scenario", "prompt": "Accounts payable receives an urgent wire request from the CEO''s display name, sent from a lookalike domain, asking them to skip the usual approval. What is this?", "choices": [{"id": "a", "text": "Ransomware"}, {"id": "b", "text": "Business email compromise"}, {"id": "c", "text": "Impossible travel"}, {"id": "d", "text": "A cloud anomaly"}], "answer": "b", "why": "Urgency, a slightly wrong domain and bypassed process are the only clues in BEC."}, {"type": "scenario", "prompt": "A cloud account suddenly has dozens of GPU instances running in a region the company never uses. What kind of indicator is this?", "choices": [{"id": "a", "text": "Identity"}, {"id": "b", "text": "Cloud anomaly"}, {"id": "c", "text": "Network"}, {"id": "d", "text": "Social engineering"}], "answer": "b", "why": "Unexpected resources in an unused region is a classic cloud anomaly."}, {"type": "callout", "variant": "tip", "text": "BEC has no malware to find; look for urgency, a lookalike domain and a skipped approval."}]'::jsonb where id = '12cc49be-1646-4e27-b09f-e3390949c5c5';

-- Core Detection Tools: Packet Analysis, SIEM, and EDR/XDR
update lessons set content_blocks = '[{"text": "Core Detection Tools: Packet Analysis, SIEM, and EDR/XDR", "type": "title", "overview": "The primary tool categories a SOC analyst uses day-to-day to detect and confirm malicious activity.", "examContext": "You''re expected to match a tool name (Wireshark, Snort, Suricata, Zeek) to its category and know what EDR/XDR adds beyond traditional antivirus."}, {"type": "compare", "heading": "Packet analysis tools", "columns": ["What it does", "Output"], "rows": [{"label": "Wireshark", "values": ["Interactive capture and deep packet inspection", "Decoded packets for manual review"]}, {"label": "Snort / Suricata", "values": ["Signature-based IDS / IPS", "Real-time alerts on known-bad traffic"]}, {"label": "Zeek", "values": ["Network security monitoring", "Rich structured logs for later analysis"]}]}, {"type": "key_term", "term": "SIEM", "definition": "Aggregates and correlates logs from endpoints, network, applications and cloud for searching, alerting and dashboards.", "example": "A correlation rule fires when a user fails MFA ten times and then succeeds from a new country."}, {"type": "compare", "heading": "EDR vs. XDR", "columns": ["EDR", "XDR"], "rows": [{"label": "Covers", "values": ["Endpoints", "Endpoints plus network, cloud and email"]}, {"label": "Detects by", "values": ["Behavior, not just signatures", "Behavior correlated across sources"]}, {"label": "Can respond", "values": ["Isolate or remediate a host", "Coordinated response across layers"]}]}, {"type": "scenario", "prompt": "A tool fired a real-time alert when traffic matched a known exploit signature. Which tool is it most likely?", "choices": [{"id": "a", "text": "Zeek"}, {"id": "b", "text": "Suricata"}, {"id": "c", "text": "Wireshark"}, {"id": "d", "text": "A SIEM dashboard"}], "answer": "b", "why": "Real-time signature alerts come from Snort or Suricata."}, {"type": "scenario", "prompt": "An analyst wants detailed connection, DNS and HTTP logs from the network to search during a hunt next week. Which tool fits?", "choices": [{"id": "a", "text": "Snort"}, {"id": "b", "text": "Zeek"}, {"id": "c", "text": "Wireshark"}, {"id": "d", "text": "EDR"}], "answer": "b", "why": "Zeek produces structured logs for later analysis rather than alerts."}, {"type": "callout", "variant": "tip", "text": "Real-time signature alert: Snort or Suricata. Structured logs for later: Zeek. Hands-on packet inspection: Wireshark."}]'::jsonb where id = '04c36d74-68ee-40e3-9dec-d3b7575b2af0';

-- Threat Intel Platforms, File Analysis, Sandboxing, and Email Analysis
update lessons set content_blocks = '[{"text": "Threat Intel Platforms, File Analysis, Sandboxing, and Email Analysis", "type": "title", "overview": "The remaining core tool categories used to determine whether a file, IP, or email is malicious.", "examContext": "Expect scenarios where you must pick the right tool to answer a specific question, is this hash known-bad, what does this file actually do, is this email spoofed?"}, {"type": "compare", "heading": "Which tool answers which question", "columns": ["Answers"], "rows": [{"label": "Threat intelligence platform (TIP)", "values": ["Is this IP, domain or hash known bad across many feeds?"]}, {"label": "Reputation tool", "values": ["A quick known-bad check on one artifact."]}, {"label": "Static file analysis", "values": ["What do the hash, strings and metadata reveal?"]}, {"label": "Sandbox", "values": ["What does this file actually do when it runs?"]}, {"label": "Email analysis", "values": ["Is this message spoofed? Check headers, SPF, DKIM, DMARC, links."]}]}, {"type": "key_term", "term": "Sandboxing", "definition": "Running a suspicious file or URL in an isolated, monitored environment to watch its real behavior.", "example": "In the sandbox, an invoice PDF drops a DLL, creates a scheduled task and contacts an IP in another country."}, {"type": "key_term", "term": "Pattern recognition", "definition": "Spotting the same hash, C2 domain or TTPs across incidents to link them to one campaign or actor.", "example": "Three separate phishing incidents all beacon to the same domain, so they''re investigated as one campaign."}, {"type": "scenario", "prompt": "Static analysis of a suspicious executable is inconclusive because the code is heavily obfuscated. What should the analyst do next?", "choices": [{"id": "a", "text": "Run it on a production workstation"}, {"id": "b", "text": "Detonate it in a sandbox"}, {"id": "c", "text": "Delete it and close the ticket"}, {"id": "d", "text": "Check its file size"}], "answer": "b", "why": "A sandbox reveals real behavior that obfuscation hides from static analysis."}, {"type": "scenario", "prompt": "A user reports a suspicious email. Which check shows whether it really came from the claimed domain?", "choices": [{"id": "a", "text": "File hash reputation"}, {"id": "b", "text": "SPF, DKIM and DMARC results in the headers"}, {"id": "c", "text": "Sandboxing the body text"}, {"id": "d", "text": "Zeek logs"}], "answer": "b", "why": "Email authentication results show whether the sender is legitimate."}, {"type": "callout", "variant": "tip", "text": "Need to know what a file does? Sandbox. Need to know if it''s already known bad? TIP or reputation lookup."}]'::jsonb where id = 'ce2b8f00-78d0-4575-bf80-5005c62d5e4f';

-- Threat Intelligence Concepts
update lessons set content_blocks = '[{"text": "Threat Intelligence Concepts", "type": "title", "overview": "The vocabulary and framework analysts use to describe who is attacking, how, and how confident they are in that assessment.", "examContext": "MITRE ATT&CK is one of the highest-yield topics on the exam, know that it catalogs real-world tactics and techniques, and be ready to map a described behavior to a tactic."}, {"type": "compare", "heading": "Threat actors", "columns": ["Motivation", "Typical traits"], "rows": [{"label": "Nation-state", "values": ["Geopolitical", "Well resourced, stealthy, persistent"]}, {"label": "Organized crime", "values": ["Money", "Ransomware, fraud, data theft"]}, {"label": "Hacktivist", "values": ["Ideology", "Defacement, leaks, DDoS"]}, {"label": "Insider threat", "values": ["Varies", "Already has legitimate access"]}]}, {"type": "diagram", "heading": "TTPs: from goal to specifics", "diagram": {"kind": "ladder", "rungs": [{"label": "Tactic", "note": "The goal. Initial access."}, {"label": "Technique", "note": "How it''s achieved. Phishing."}, {"label": "Procedure", "note": "This actor''s exact method. A macro-laden invoice sent from a compromised vendor."}], "top": "most general", "bottom": "most specific"}}, {"type": "key_term", "term": "MITRE ATT&CK", "definition": "A public, continuously updated knowledge base of real-world adversary tactics and techniques, arranged as a matrix.", "example": "An analyst maps \"dumped LSASS memory\" to the Credential Access tactic, technique T1003."}, {"type": "term_set", "heading": "Confidence, collection and IoCs", "terms": [{"term": "Confidence level", "short": "Low, medium or high, based on source reliability and corroboration."}, {"term": "Collection", "short": "OSINT, commercial feeds, ISACs, internal telemetry."}, {"term": "Indicator of compromise", "short": "A hash, IP, domain or registry key suggesting compromise."}]}, {"type": "scenario", "prompt": "A report says an actor \"uses spearphishing attachments to gain initial access\". What is \"spearphishing attachment\" in ATT&CK terms?", "choices": [{"id": "a", "text": "Tactic"}, {"id": "b", "text": "Technique"}, {"id": "c", "text": "Procedure"}, {"id": "d", "text": "IoC"}], "answer": "b", "why": "Initial access is the tactic; the method used to achieve it is the technique."}, {"type": "scenario", "prompt": "A single, uncorroborated forum post names an IP as malicious. How should it be treated?", "choices": [{"id": "a", "text": "As confirmed fact"}, {"id": "b", "text": "As low-confidence intel to corroborate"}, {"id": "c", "text": "As an IoC to block everywhere immediately"}, {"id": "d", "text": "As irrelevant"}], "answer": "b", "why": "Intel carries a confidence level; one unverified source is low confidence."}, {"type": "callout", "variant": "tip", "text": "Tactic is why, technique is how, procedure is exactly how this actor did it."}]'::jsonb where id = 'b36dd07e-ef33-4c64-916a-83f37388ab91';

-- Threat Hunting and Threat Modeling
update lessons set content_blocks = '[{"text": "Threat Hunting and Threat Modeling", "type": "title", "overview": "Moving from reactive alert investigation to proactively searching for undetected compromise, and structuring that search with a threat model.", "examContext": "Know the difference between threat hunting (proactive, hypothesis-driven) and simply responding to an alert (reactive), and be ready to recognize STRIDE''s six categories."}, {"type": "compare", "heading": "Hunting vs. responding", "columns": ["Threat hunting", "Alert response"], "rows": [{"label": "Trigger", "values": ["A hypothesis", "An alert"]}, {"label": "Stance", "values": ["Proactive; assumes breach", "Reactive"]}, {"label": "Finds", "values": ["What tools missed", "What tools flagged"]}]}, {"type": "key_term", "term": "Hunting hypothesis", "definition": "A testable idea, usually from threat intel, that guides the search.", "example": "\"Actor X targets our industry and uses WMI for lateral movement. Do we see unusual WMI activity between workstations?\""}, {"type": "term_set", "heading": "STRIDE", "terms": [{"term": "Spoofing", "short": "Pretending to be someone else."}, {"term": "Tampering", "short": "Altering data or code."}, {"term": "Repudiation", "short": "Denying an action with no proof otherwise."}, {"term": "Information disclosure", "short": "Exposing data to the wrong people."}, {"term": "Denial of service", "short": "Making a system unavailable."}, {"term": "Elevation of privilege", "short": "Gaining rights you shouldn''t have."}], "intro": "A threat modeling framework for thinking through what could go wrong during design or review."}, {"type": "compare", "heading": "Cyber deception", "columns": ["Honeypot", "Honeytoken"], "rows": [{"label": "What it is", "values": ["A decoy system", "Decoy data: fake credentials or records"]}, {"label": "Alerts when", "values": ["Anyone interacts with it", "The decoy is used or accessed"]}, {"label": "False positives", "values": ["Almost none", "Almost none"]}]}, {"type": "scenario", "prompt": "A fake \"svc_backup_admin\" credential planted in a config file is used to log in. What happened?", "choices": [{"id": "a", "text": "A false positive"}, {"id": "b", "text": "A honeytoken caught unauthorized access"}, {"id": "c", "text": "A honeypot failed"}, {"id": "d", "text": "Impossible travel"}], "answer": "b", "why": "No legitimate user has a reason to use decoy credentials."}, {"type": "scenario", "prompt": "Which STRIDE category covers a user who deletes logs so they can later deny making a transfer?", "choices": [{"id": "a", "text": "Spoofing"}, {"id": "b", "text": "Tampering"}, {"id": "c", "text": "Repudiation"}, {"id": "d", "text": "Elevation of privilege"}], "answer": "c", "why": "Being able to deny an action is repudiation."}, {"type": "callout", "variant": "tip", "text": "Hunting starts from a hypothesis, not an alert. Decoy alerts have almost no false positives."}]'::jsonb where id = '3fb82ba8-b37d-480a-bad4-3db813b8d6b0';

-- Efficiency and Process Improvement in Security Operations
update lessons set content_blocks = '[{"text": "Efficiency and Process Improvement in Security Operations", "type": "title", "overview": "How SOCs scale their limited analyst time through standardization and automation rather than simply hiring more people.", "examContext": "Know the distinction between a playbook (decision-making guidance) and a runbook (a specific step-by-step procedure), and what SOAR actually automates."}, {"type": "compare", "heading": "Playbook vs. runbook", "columns": ["Playbook", "Runbook"], "rows": [{"label": "Level", "values": ["Decision guidance for an incident type", "Exact steps for one task"]}, {"label": "Example", "values": ["How we handle phishing reports", "How to quarantine a mailbox, click by click"]}]}, {"type": "compare", "heading": "SIEM vs. SOAR", "columns": ["SIEM", "SOAR"], "rows": [{"label": "Main job", "values": ["Aggregate, correlate, alert", "Orchestrate automated response across tools"]}, {"label": "Example", "values": ["Raises an alert for a malicious IP", "Enriches it, blocks the IP on the firewall and opens a ticket"]}], "cue": ["\"Aggregates and alerts\"", "\"Automatically takes action across tools\""]}, {"type": "term_set", "heading": "Automation building blocks", "terms": [{"term": "Data enrichment", "short": "Geolocation, reputation and asset owner added to alerts automatically."}, {"term": "API integration", "short": "Tools exchange data and trigger actions without copy and paste."}, {"term": "Infrastructure as Code", "short": "Secure baselines deployed consistently from version control."}]}, {"type": "scenario", "prompt": "A platform receives a phishing alert, looks up the sender''s reputation, deletes the message from every mailbox and opens a ticket, with no analyst involved. What is it?", "choices": [{"id": "a", "text": "SIEM"}, {"id": "b", "text": "SOAR"}, {"id": "c", "text": "TIP"}, {"id": "d", "text": "EDR"}], "answer": "b", "why": "Orchestrating actions across several tools from a playbook is SOAR."}, {"type": "scenario", "prompt": "A document lists the exact commands to isolate a host in the EDR console. Is this a playbook or a runbook?", "choices": [{"id": "a", "text": "Playbook"}, {"id": "b", "text": "Runbook"}, {"id": "c", "text": "Policy"}, {"id": "d", "text": "SLA"}], "answer": "b", "why": "Exact steps for a single task make it a runbook."}, {"type": "callout", "variant": "tip", "text": "Playbook decides; runbook does. SIEM alerts; SOAR acts."}]'::jsonb where id = 'e5559adc-ffb8-47c5-81e1-7241c00dce1e';

-- AI in Security Operations
update lessons set content_blocks = '[{"text": "AI in Security Operations", "type": "title", "overview": "CS0-004 added an entirely new sub-objective on AI, both its risks when used carelessly and its practical value when used correctly in a SOC.", "examContext": "This is new material with no CS0-003 equivalent, don''t assume older study guides cover it, and expect questions on both AI risks and legitimate SOC use cases."}, {"type": "compare", "heading": "AI risks", "columns": ["What it is", "Example"], "rows": [{"label": "Hallucination", "values": ["Plausible but false output", "An AI summary cites a malicious IP that never appeared in the logs"]}, {"label": "Model poisoning", "values": ["Corrupted training data changes the model''s behavior", "A detector learns to call one malware family benign"]}, {"label": "Data exposure", "values": ["Sensitive data sent to a third-party AI tool", "An analyst pastes customer records into a public chatbot"]}]}, {"type": "term_set", "heading": "Governance", "terms": [{"term": "Data sharing policy", "short": "What may and may not go into AI tools."}, {"term": "Human review", "short": "Required before acting on AI output."}, {"term": "Audit trail", "short": "A record of AI-assisted decisions."}]}, {"type": "term_set", "heading": "Good uses in the SOC", "terms": [{"term": "Log analysis", "short": "Surface anomalies in huge log volumes."}, {"term": "Investigation", "short": "Summarize a timeline from raw data."}, {"term": "Drafting", "short": "First-pass reports or responses for a human to review."}]}, {"type": "scenario", "prompt": "An AI assistant recommends blocking a list of IPs it says were in the attack. What should the analyst do?", "choices": [{"id": "a", "text": "Block them immediately"}, {"id": "b", "text": "Verify each against the actual evidence before acting"}, {"id": "c", "text": "Ignore AI output entirely"}, {"id": "d", "text": "Forward the list to leadership"}], "answer": "b", "why": "AI assists, humans verify. Hallucinated indicators are a real risk."}, {"type": "scenario", "prompt": "An attacker slips mislabeled samples into a vendor''s training data so its detector ignores their malware. What is this?", "choices": [{"id": "a", "text": "Hallucination"}, {"id": "b", "text": "Model poisoning"}, {"id": "c", "text": "Data exposure"}, {"id": "d", "text": "Prompt engineering"}], "answer": "b", "why": "Corrupting training data is model poisoning."}, {"type": "callout", "variant": "tip", "text": "The exam''s rule for AI: it assists, humans verify. Acting on AI output without validation is almost always wrong."}]'::jsonb where id = '26a384cf-3a9c-4a77-97f6-daedfdb13d18';

-- Domain 1 Recap: Security Operations
update lessons set content_blocks = '[{"text": "Domain 1 Recap: Security Operations", "type": "title", "overview": "The highest-yield facts from Domain 1, pulled together for a final review before the domain checkpoint.", "examContext": "Read through once, then take the Domain 1 Checkpoint, it uses fresh scenarios, not the same questions from the lesson mini-exams."}, {"type": "term_set", "heading": "Architecture and indicators", "terms": [{"term": "Time sync", "short": "Without NTP, no reliable timeline."}, {"term": "Serverless", "short": "Invocation logs are the only evidence."}, {"term": "Zero trust / SASE", "short": "Verify every request / delivered from the cloud."}, {"term": "Beaconing", "short": "Periodic outbound C2 traffic."}, {"term": "Office spawning a shell", "short": "Malicious macro."}, {"term": "Impossible travel / BEC", "short": "Stolen credentials / social engineering, no malware."}]}, {"type": "term_set", "heading": "Tools and intel", "terms": [{"term": "Snort, Suricata / Zeek / Wireshark", "short": "Real-time alerts / structured logs / manual inspection."}, {"term": "EDR / XDR", "short": "Endpoint / across layers."}, {"term": "Sandbox", "short": "Shows what a file actually does."}, {"term": "Tactic, technique, procedure", "short": "Why, how, exactly how."}, {"term": "Honeypot, honeytoken", "short": "Near-zero false positives."}, {"term": "STRIDE", "short": "Spoofing, tampering, repudiation, disclosure, DoS, elevation."}]}, {"type": "term_set", "heading": "Efficiency and AI", "terms": [{"term": "Playbook / runbook", "short": "Decisions / exact steps."}, {"term": "SOAR", "short": "Automated action across tools."}, {"term": "AI", "short": "Hallucination, poisoning, data exposure. AI assists, humans verify."}]}, {"type": "scenario", "prompt": "Which tool produces structured network logs rather than real-time alerts?", "choices": [{"id": "a", "text": "Snort"}, {"id": "b", "text": "Zeek"}, {"id": "c", "text": "Suricata"}, {"id": "d", "text": "Wireshark"}], "answer": "b", "why": "Zeek is log oriented."}, {"type": "scenario", "prompt": "A user logs in from two continents within 15 minutes. Which indicator is this?", "choices": [{"id": "a", "text": "Beaconing"}, {"id": "b", "text": "Impossible travel"}, {"id": "c", "text": "LOLBin"}, {"id": "d", "text": "BEC"}], "answer": "b", "why": "Physically impossible logins point to stolen credentials."}, {"type": "scenario", "prompt": "Which platform automatically enriches alerts and blocks IPs across tools?", "choices": [{"id": "a", "text": "SIEM"}, {"id": "b", "text": "SOAR"}, {"id": "c", "text": "TIP"}, {"id": "d", "text": "IDS"}], "answer": "b", "why": "SOAR orchestrates response."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Domain Checkpoint: fresh scenarios from every lesson in this domain."}]'::jsonb where id = 'c24220d0-7952-4f04-8b91-4bd12f9cc046';

-- Vulnerability Scanning Methods
update lessons set content_blocks = '[{"text": "Vulnerability Scanning Methods", "type": "title", "overview": "The foundational decisions behind any vulnerability scanning program, what to scan, how often, and with what level of access.", "examContext": "Expect questions asking you to pick the right scan type for a given constraint, such as needing accurate results without disrupting production."}, {"type": "paragraph", "text": "You can''t scan what you don''t know exists. An accurate **asset inventory** comes first, then a **schedule** that balances thoroughness against impact on production."}, {"type": "compare", "heading": "Credentialed vs. non-credentialed", "columns": ["Credentialed", "Non-credentialed"], "rows": [{"label": "Access", "values": ["Logs in to the target", "Probes from outside"]}, {"label": "Sees", "values": ["Installed versions, patch levels, configuration", "What an attacker sees"]}, {"label": "Accuracy", "values": ["High", "More false positives and negatives"]}], "cue": ["\"Most accurate results\"", "\"Attacker''s view\""]}, {"type": "compare", "heading": "Active vs. passive", "columns": ["Active", "Passive"], "rows": [{"label": "Method", "values": ["Sends probes and connection attempts", "Watches traffic only"]}, {"label": "Risk to fragile systems", "values": ["Can disrupt them", "None"]}]}, {"type": "term_set", "heading": "Other scan types", "terms": [{"term": "Discovery scan", "short": "Finds what''s on the network; feeds the asset inventory."}, {"term": "Baseline scan", "short": "Checks configuration against PCI DSS, CIS Benchmarks or ISO 27000, not just CVEs."}]}, {"type": "scenario", "prompt": "A team needs the most accurate picture of missing patches on its Windows servers and can provide a service account. Which scan?", "choices": [{"id": "a", "text": "Non-credentialed"}, {"id": "b", "text": "Credentialed"}, {"id": "c", "text": "Passive"}, {"id": "d", "text": "Discovery"}], "answer": "b", "why": "Logging in lets the scanner read real patch levels."}, {"type": "scenario", "prompt": "Before scanning for vulnerabilities, a team realizes it doesn''t know which hosts exist on a new network segment. What should run first?", "choices": [{"id": "a", "text": "Baseline scan"}, {"id": "b", "text": "Discovery scan"}, {"id": "c", "text": "Credentialed scan"}, {"id": "d", "text": "Penetration test"}], "answer": "b", "why": "Discovery builds the inventory deeper scans depend on."}, {"type": "callout", "variant": "tip", "text": "Most accurate: credentialed. Can''t touch the system: passive. Don''t know what''s there: discovery first."}]'::jsonb where id = '260e6761-06bb-459a-920e-30fce991f28c';

-- Specialized Scanning Considerations
update lessons set content_blocks = '[{"text": "Specialized Scanning Considerations", "type": "title", "overview": "Not every environment can be scanned the same way, fragile, ephemeral, and layered environments each need adjustments to standard scanning practice.", "examContext": "Watch for scenarios describing a specific environment type (ICS/OT, containers, cloud, web apps) and asking what scanning adjustment is appropriate."}, {"type": "compare", "heading": "Scanning by environment", "columns": ["Challenge", "Adjustment"], "rows": [{"label": "ICS / OT", "values": ["Fragile legacy systems; scans can cause physical disruption", "Passive scanning or maintenance windows; segmentation as a compensating control"]}, {"label": "Containers", "values": ["Running containers are short-lived", "Scan images before deployment"]}, {"label": "Cloud", "values": ["Auto-scaling resources come and go between scans", "Continuous, API-driven discovery rather than fixed IP schedules"]}, {"label": "Web applications", "values": ["Flaws live in the application layer", "A web app scanner that crawls and interacts with the app"]}]}, {"type": "key_term", "term": "Container image scanning", "definition": "Checks image layers for vulnerable packages and misconfigurations before deployment, shifting detection earlier.", "example": "The pipeline blocks an image because its base layer has a critical OpenSSL flaw, before it ever reaches production."}, {"type": "key_term", "term": "Scope agreement", "definition": "Written authorization that explicitly covers each environment, including cloud accounts, registries and ICS networks.", "example": "The scan is paused because the authorization covered the on-premises network but not the company''s AWS accounts."}, {"type": "scenario", "prompt": "A water utility needs to assess PLCs that can''t tolerate disruption. What approach fits?", "choices": [{"id": "a", "text": "Aggressive active scan during business hours"}, {"id": "b", "text": "Passive scanning or a maintenance-window scan"}, {"id": "c", "text": "Non-credentialed internet scan"}, {"id": "d", "text": "Skip assessment entirely"}], "answer": "b", "why": "ICS and \"can''t tolerate disruption\" signal passive or scheduled scanning."}, {"type": "scenario", "prompt": "A weekly IP-based scan keeps missing cloud instances that live only a few hours. What''s the issue?", "choices": [{"id": "a", "text": "Scope agreement"}, {"id": "b", "text": "Ephemeral resources falling between scan windows"}, {"id": "c", "text": "False negatives in CVSS"}, {"id": "d", "text": "Credentialed scanning"}], "answer": "b", "why": "Short-lived cloud assets escape fixed schedules."}, {"type": "callout", "variant": "tip", "text": "ICS plus \"can''t be disrupted\" means passive or maintenance window. Containers: scan the image before it ships."}]'::jsonb where id = 'b0d864aa-3d42-422b-ae6a-9189b1ca72fd';

-- Network and Web Application Scanning Tools
update lessons set content_blocks = '[{"text": "Network and Web Application Scanning Tools", "type": "title", "overview": "The specific tools analysts use for network discovery/port scanning versus testing web applications for flaws.", "examContext": "Know which tool belongs in which category, the exam will name a specific tool and expect you to recognize what it''s for."}, {"type": "compare", "heading": "Network scanners", "columns": ["Strength", "Use when"], "rows": [{"label": "Nmap", "values": ["Discovery, ports, services, OS fingerprinting", "Depth on a manageable scope"]}, {"label": "Masscan", "values": ["Extreme speed", "Huge address ranges, quickly"]}, {"label": "Angry IP Scanner", "values": ["Lightweight and simple", "Quick host discovery"]}]}, {"type": "compare", "heading": "Web application tools", "columns": ["Type", "Notes"], "rows": [{"label": "Burp Suite", "values": ["Intercepting proxy, scanner and manual tools", "De facto standard for web app testing"]}, {"label": "OWASP ZAP", "values": ["Free proxy and scanner", "Popular in CI/CD pipelines"]}, {"label": "Nikto", "values": ["Web server scanner", "Outdated software, dangerous files, misconfigurations"]}]}, {"type": "scenario", "prompt": "A team needs to sweep an entire /8 for open port 443 as fast as possible. Which tool?", "choices": [{"id": "a", "text": "Nmap"}, {"id": "b", "text": "Masscan"}, {"id": "c", "text": "Nikto"}, {"id": "d", "text": "Burp Suite"}], "answer": "b", "why": "Masscan trades depth for raw speed."}, {"type": "scenario", "prompt": "A tester wants to intercept and modify requests between a browser and a web app. Which tool?", "choices": [{"id": "a", "text": "Nikto"}, {"id": "b", "text": "Burp Suite"}, {"id": "c", "text": "Masscan"}, {"id": "d", "text": "Angry IP Scanner"}], "answer": "b", "why": "Burp''s intercepting proxy does exactly this."}, {"type": "callout", "variant": "tip", "text": "Speed: Masscan. Depth: Nmap. Intercept and test a web app: Burp or ZAP. Web server misconfig: Nikto."}]'::jsonb where id = 'bb79bdac-6e4c-433f-a4a4-8a1addf702d4';

-- Vulnerability Scanners and Cloud Security Tools
update lessons set content_blocks = '[{"text": "Vulnerability Scanners and Cloud Security Tools", "type": "title", "overview": "Purpose-built vulnerability scanners versus the newer generation of cloud-native and infrastructure-as-code security tools.", "examContext": "Know that cloud-native tools like Prowler, Trivy, and Checkov target different layers, cloud config, container images, and IaC templates respectively."}, {"type": "term_set", "heading": "Vulnerability scanners", "terms": [{"term": "Nessus", "short": "Commercial; wide plugin-based CVE coverage."}, {"term": "OpenVAS", "short": "Free and open source with similar core features."}, {"term": "Nuclei", "short": "Fast, template based; community templates for new CVEs."}]}, {"type": "key_term", "term": "CSPM", "definition": "Cloud security posture management: continuously checks cloud configuration against best practices and compliance frameworks.", "example": "A CSPM alert flags an S3 bucket made public an hour ago and an IAM role with wildcard permissions."}, {"type": "compare", "heading": "Cloud-native tools by pipeline stage", "columns": ["Scans", "Stage"], "rows": [{"label": "Checkov", "values": ["IaC templates: Terraform, CloudFormation, Kubernetes", "Before deployment"]}, {"label": "Trivy", "values": ["Container images, filesystems, IaC", "Build and deploy"]}, {"label": "Prowler", "values": ["Live AWS, Azure and GCP accounts", "After deployment"]}]}, {"type": "scenario", "prompt": "A team wants to catch an open security group in a Terraform file before anything is provisioned. Which tool?", "choices": [{"id": "a", "text": "Prowler"}, {"id": "b", "text": "Checkov"}, {"id": "c", "text": "Nessus"}, {"id": "d", "text": "Nikto"}], "answer": "b", "why": "Checkov statically analyzes IaC before deployment."}, {"type": "scenario", "prompt": "Which tool audits an already running AWS account against security benchmarks?", "choices": [{"id": "a", "text": "Checkov"}, {"id": "b", "text": "Prowler"}, {"id": "c", "text": "Trivy"}, {"id": "d", "text": "Masscan"}], "answer": "b", "why": "Prowler is a CSPM tool for live accounts."}, {"type": "callout", "variant": "tip", "text": "Checkov before deployment, Prowler after. Trivy scans containers."}]'::jsonb where id = '239e9727-aa93-47ce-a11c-8147f2e26788';

-- Prioritizing Vulnerabilities: CVSS and EPSS
update lessons set content_blocks = '[{"text": "Prioritizing Vulnerabilities: CVSS and EPSS", "type": "title", "overview": "No organization can patch everything immediately, prioritization frameworks decide what gets fixed first.", "examContext": "Know that CVSS scores severity (how bad IF exploited) while EPSS scores likelihood (how likely TO BE exploited), the exam tests whether you can combine both with asset value for real prioritization."}, {"type": "compare", "heading": "CVSS vs. EPSS", "columns": ["CVSS", "EPSS"], "rows": [{"label": "Measures", "values": ["Severity if exploited", "Likelihood of exploitation soon"]}, {"label": "Scale", "values": ["0 to 10", "0 to 1, a probability"]}, {"label": "Based on", "values": ["Attack vector, complexity, privileges, impact", "Real-world exploitation data"]}], "cue": ["\"How bad\"", "\"How likely\""]}, {"type": "diagram", "heading": "What makes something patch-first", "diagram": {"kind": "triad", "points": [{"label": "High CVSS", "note": "Severe if exploited."}, {"label": "High EPSS", "note": "Likely to be exploited."}, {"label": "Critical asset", "note": "Matters to the business."}], "center": "fix now"}, "caption": "Threat intel showing active exploitation in the wild pushes priority up further."}, {"type": "compare", "heading": "Mitigation vs. remediation", "columns": ["Mitigation", "Remediation"], "rows": [{"label": "Effect", "values": ["Reduces risk", "Resolves the vulnerability"]}, {"label": "Example", "values": ["WAF rule blocking the exploit path", "Applying the vendor patch"]}]}, {"type": "scenario", "prompt": "Which should be fixed first?", "choices": [{"id": "a", "text": "CVSS 9.8, EPSS 0.02, isolated lab server"}, {"id": "b", "text": "CVSS 8.1, EPSS 0.91, internet-facing payment API"}, {"id": "c", "text": "CVSS 5.0, EPSS 0.10, internal wiki"}, {"id": "d", "text": "CVSS 9.0, EPSS 0.05, retired test VM"}], "answer": "b", "why": "High likelihood of exploitation on a critical, exposed asset beats a slightly higher severity score elsewhere.", "trap": "The 9.8 is tempting, but CVSS alone doesn''t measure likelihood or business value."}, {"type": "scenario", "prompt": "A patch isn''t available yet, so the team blocks the vulnerable endpoint at the load balancer. What is this?", "choices": [{"id": "a", "text": "Remediation"}, {"id": "b", "text": "Mitigation"}, {"id": "c", "text": "Risk transfer"}, {"id": "d", "text": "Acceptance"}], "answer": "b", "why": "It reduces risk without resolving the flaw."}, {"type": "callout", "variant": "tip", "text": "CVSS is how bad, EPSS is how likely. Combine both with asset value."}]'::jsonb where id = '3353e8d3-70c2-4dc8-94d7-d3bf52b8c154';

-- Validating and Contextualizing Vulnerability Data
update lessons set content_blocks = '[{"text": "Validating and Contextualizing Vulnerability Data", "type": "title", "overview": "Raw scanner output isn''t the final answer, findings need validation before action, and fixes need validation after action.", "examContext": "Expect scenarios asking whether a finding is a true positive, false positive, and what step confirms a fix actually worked."}, {"type": "compare", "heading": "False positive vs. false negative", "columns": ["False positive", "False negative"], "rows": [{"label": "Meaning", "values": ["Reported but not real", "Real but missed"]}, {"label": "Cost", "values": ["Wasted effort", "False confidence and open risk"]}, {"label": "Worse?", "values": ["Less serious", "More serious"]}]}, {"type": "key_term", "term": "Remediation validation", "definition": "Rescan or retest after a fix to confirm the vulnerability is actually gone.", "example": "The patch was deployed, but the rescan still flags the server: the service was never restarted."}, {"type": "term_set", "heading": "Context changes urgency", "terms": [{"term": "Exposure", "short": "Internet facing is far more urgent than air gapped."}, {"term": "Compensating controls", "short": "A firewall or segment may already block the path."}, {"term": "Exceptions", "short": "Deferred findings are documented with a reason and review date."}]}, {"type": "scenario", "prompt": "After patching, how should the team confirm the fix worked?", "choices": [{"id": "a", "text": "Close the ticket"}, {"id": "b", "text": "Rescan the system"}, {"id": "c", "text": "Check the CVSS score"}, {"id": "d", "text": "Ask the system owner"}], "answer": "b", "why": "Validation by rescanning is the only proof."}, {"type": "scenario", "prompt": "A scanner says Apache is vulnerable, but the server runs nginx and has no Apache installed. What is this?", "choices": [{"id": "a", "text": "True positive"}, {"id": "b", "text": "False positive"}, {"id": "c", "text": "False negative"}, {"id": "d", "text": "Compensating control"}], "answer": "b", "why": "It flagged something that isn''t there."}, {"type": "callout", "variant": "tip", "text": "A missed real flaw is worse than a false alarm. Always rescan after fixing."}]'::jsonb where id = '2847cc69-38f5-40c9-80a7-94757e3d4306';

-- Control Types and Risk Management
update lessons set content_blocks = '[{"text": "Control Types and Risk Management", "type": "title", "overview": "The categories of security controls available to address a vulnerability, and the strategic choices for handling risk that can''t be fully eliminated.", "examContext": "Expect scenarios naming a specific control and asking you to categorize it, and scenarios asking which risk strategy a described business decision represents."}, {"type": "compare", "heading": "Control types", "columns": ["Examples"], "rows": [{"label": "Administrative", "values": ["Policies, procedures, awareness training"]}, {"label": "Technical", "values": ["Firewalls, encryption, MFA"]}, {"label": "Physical", "values": ["Badge readers, locks, cameras"]}]}, {"type": "compare", "heading": "Four risk strategies", "columns": ["What it means", "Example"], "rows": [{"label": "Accept", "values": ["Knowingly take no further action", "Low-impact risk where the fix costs more"]}, {"label": "Transfer", "values": ["Shift the financial impact", "Cyber insurance"]}, {"label": "Avoid", "values": ["Stop the activity", "Retire the legacy app"]}, {"label": "Mitigate", "values": ["Reduce likelihood or impact", "Add segmentation"]}]}, {"type": "key_term", "term": "Risk acceptance", "definition": "A formal, documented decision to take no further action because the cost outweighs the impact, or the risk is within tolerance.", "example": "Management signs off on leaving an internal kiosk unpatched for six months, with a review date."}, {"type": "scenario", "prompt": "A company buys a policy that pays for breach response costs. Which strategy?", "choices": [{"id": "a", "text": "Accept"}, {"id": "b", "text": "Transfer"}, {"id": "c", "text": "Avoid"}, {"id": "d", "text": "Mitigate"}], "answer": "b", "why": "Insurance is the textbook risk transfer."}, {"type": "scenario", "prompt": "A mandatory security awareness program is what type of control?", "choices": [{"id": "a", "text": "Technical"}, {"id": "b", "text": "Administrative"}, {"id": "c", "text": "Physical"}, {"id": "d", "text": "Compensating"}], "answer": "b", "why": "Training and policy are administrative."}, {"type": "callout", "variant": "tip", "text": "Insurance means transfer. Training and policy are administrative."}]'::jsonb where id = '645f3c7c-9787-4319-ad03-3a4f9c34d596';

-- Secure Application Development Concepts
update lessons set content_blocks = '[{"text": "Secure Application Development Concepts", "type": "title", "overview": "How vulnerabilities are found during the software development process itself, and the growing risk introduced by third-party and open-source dependencies.", "examContext": "Know the SAST vs. DAST distinction cold, it''s one of the exam''s most frequently tested application security comparisons."}, {"type": "compare", "heading": "SAST vs. DAST", "columns": ["SAST", "DAST"], "rows": [{"label": "Tests", "values": ["Source code, bytecode or binaries", "A running application"]}, {"label": "Runs the code?", "values": ["No", "Yes, from the outside"]}, {"label": "When", "values": ["Early in development", "Later, against a live build"]}, {"label": "Misses", "values": ["Runtime-only issues", "Code paths it never reaches"]}], "cue": ["\"Code review without running it\"", "\"Attacking the live app\""]}, {"type": "key_term", "term": "Software supply chain risk", "definition": "Risk from third-party and open-source components; a flaw anywhere in the chain reaches every app that depends on it.", "example": "A popular logging library is found vulnerable, affecting hundreds of internal apps that never imported it directly."}, {"type": "term_set", "heading": "Managing third-party risk", "terms": [{"term": "SBOM", "short": "A full inventory of components, so exposure to a new flaw is answered in minutes."}, {"term": "Vendor risk assessment", "short": "Evaluate a supplier''s security before integrating."}, {"term": "Dependency scanning", "short": "Check libraries against known-vulnerability databases automatically."}]}, {"type": "scenario", "prompt": "A tool analyzes source code for injection flaws without executing it. What is it?", "choices": [{"id": "a", "text": "DAST"}, {"id": "b", "text": "SAST"}, {"id": "c", "text": "Fuzzing"}, {"id": "d", "text": "Penetration testing"}], "answer": "b", "why": "Analysis without execution is static."}, {"type": "scenario", "prompt": "A new critical flaw is announced in a common library. What lets the team know within minutes which apps include it?", "choices": [{"id": "a", "text": "CVSS"}, {"id": "b", "text": "An SBOM"}, {"id": "c", "text": "DAST"}, {"id": "d", "text": "A risk register"}], "answer": "b", "why": "An SBOM lists every component in each app."}, {"type": "callout", "variant": "tip", "text": "SAST reads the code; DAST attacks the running app. An SBOM answers \"are we affected?\""}]'::jsonb where id = '2a9bc0d8-2567-4a94-a181-3d2330a38eff';

-- Domain 2 Recap: Vulnerability Management
update lessons set content_blocks = '[{"text": "Domain 2 Recap: Vulnerability Management", "type": "title", "overview": "The highest-yield facts from Domain 2, pulled together for a final review before the domain checkpoint.", "examContext": "Read through once, then take the Domain 2 Checkpoint, it uses fresh scenarios, not the same questions from the lesson mini-exams."}, {"type": "term_set", "heading": "Scanning", "terms": [{"term": "Asset inventory", "short": "Comes first."}, {"term": "Credentialed", "short": "Most accurate."}, {"term": "Passive", "short": "For systems that can''t be probed."}, {"term": "ICS / OT", "short": "Passive or maintenance windows."}, {"term": "Container images", "short": "Scan before deployment."}]}, {"type": "term_set", "heading": "Tools", "terms": [{"term": "Nmap / Masscan", "short": "Depth / speed."}, {"term": "Burp, ZAP / Nikto", "short": "Web app testing / web server misconfig."}, {"term": "Nessus, OpenVAS, Nuclei", "short": "Vulnerability scanners."}, {"term": "Checkov / Trivy / Prowler", "short": "IaC before deploy / containers / live cloud."}]}, {"type": "term_set", "heading": "Prioritize, validate, manage", "terms": [{"term": "CVSS / EPSS", "short": "Severity / likelihood."}, {"term": "Mitigate / remediate", "short": "Reduce / resolve."}, {"term": "False negative", "short": "Worse than a false positive."}, {"term": "Accept, transfer, avoid, mitigate", "short": "Insurance is transfer."}, {"term": "SAST / DAST / SBOM", "short": "Code / running app / component inventory."}]}, {"type": "scenario", "prompt": "Which score estimates how likely a vulnerability is to be exploited?", "choices": [{"id": "a", "text": "CVSS"}, {"id": "b", "text": "EPSS"}, {"id": "c", "text": "CWE"}, {"id": "d", "text": "CVE"}], "answer": "b", "why": "EPSS is a probability of exploitation."}, {"type": "scenario", "prompt": "Which tool scans Terraform before deployment?", "choices": [{"id": "a", "text": "Prowler"}, {"id": "b", "text": "Checkov"}, {"id": "c", "text": "Nmap"}, {"id": "d", "text": "Nikto"}], "answer": "b", "why": "Checkov is static IaC analysis."}, {"type": "scenario", "prompt": "What confirms a remediation worked?", "choices": [{"id": "a", "text": "A new SBOM"}, {"id": "b", "text": "A rescan"}, {"id": "c", "text": "Risk acceptance"}, {"id": "d", "text": "A CVSS recalculation"}], "answer": "b", "why": "Validate by rescanning."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Domain Checkpoint: fresh scenarios from every lesson in this domain."}]'::jsonb where id = 'b665931f-217f-4c9c-885f-412f569d76d3';

-- The Cyber Kill Chain and Diamond Model of Intrusion Analysis
update lessons set content_blocks = '[{"text": "The Cyber Kill Chain and Diamond Model of Intrusion Analysis", "type": "title", "overview": "Two complementary frameworks analysts use to structure how they think about an attack, one as a sequence of stages, the other as a relationship between four elements.", "examContext": "Know the Kill Chain''s stage order and what the Diamond Model''s four core vertices represent, both are frequently tested by name."}, {"type": "diagram", "heading": "The Cyber Kill Chain", "diagram": {"kind": "flow", "steps": [{"label": "Reconnaissance", "note": "Research the target."}, {"label": "Weaponization", "note": "Build the payload."}, {"label": "Delivery", "note": "Send it: email, web, USB."}, {"label": "Exploitation", "note": "Trigger the vulnerability."}, {"label": "Installation", "note": "Establish persistence."}, {"label": "Command and control", "note": "Open a channel back."}, {"label": "Actions on objectives", "note": "Steal, encrypt, destroy."}]}, "caption": "Break the chain at any stage and the attack stops; the earlier, the less damage."}, {"type": "diagram", "heading": "The Diamond Model", "diagram": {"kind": "triad", "points": [{"label": "Adversary", "note": "Who."}, {"label": "Capability", "note": "The tool or malware."}, {"label": "Infrastructure", "note": "Domains, IPs and servers used."}], "center": "Victim"}, "caption": "Four connected vertices: adversary, capability, infrastructure and victim. Know one and pivot to the others."}, {"type": "compare", "heading": "Kill Chain vs. Diamond Model", "columns": ["Kill Chain", "Diamond Model"], "rows": [{"label": "Shape", "values": ["Sequential stages", "Relationships between four elements"]}, {"label": "Best for", "values": ["Seeing where the attack was stopped and what''s missing earlier", "Pivoting from a known element to find others"]}]}, {"type": "scenario", "prompt": "An attacker''s malware creates a scheduled task to survive reboots. Which Kill Chain stage?", "choices": [{"id": "a", "text": "Delivery"}, {"id": "b", "text": "Exploitation"}, {"id": "c", "text": "Installation"}, {"id": "d", "text": "Command and control"}], "answer": "c", "why": "Persistence is installation."}, {"type": "scenario", "prompt": "An analyst knows a C2 domain from one incident and searches for other malware and victims tied to it. Which framework supports this pivot?", "choices": [{"id": "a", "text": "Kill Chain"}, {"id": "b", "text": "Diamond Model"}, {"id": "c", "text": "STRIDE"}, {"id": "d", "text": "CVSS"}], "answer": "b", "why": "The Diamond Model is built for pivoting between vertices."}, {"type": "callout", "variant": "tip", "text": "Recon, weaponize, deliver, exploit, install, C2, actions. Diamond: adversary, capability, infrastructure, victim."}]'::jsonb where id = 'bbe7b6c9-8716-4a60-b2e8-8410ec12465f';

-- The MITRE ATT&CK Framework in Incident Response
update lessons set content_blocks = '[{"text": "The MITRE ATT&CK Framework in Incident Response", "type": "title", "overview": "How MITRE ATT&CK, introduced in Domain 1 as a threat intelligence concept, is applied practically during incident response.", "examContext": "Domain 3 tests ATT&CK from the incident-response angle: mapping observed behavior during an active investigation, not just describing the framework abstractly."}, {"type": "paragraph", "text": "During an incident, responders use **MITRE ATT&CK** to name exactly what the adversary did, in language the whole team, leadership and future defenders share."}, {"type": "key_term", "term": "ATT&CK Navigator", "definition": "A visualization tool for highlighting and annotating the techniques seen in an incident, which makes detection gaps obvious.", "example": "The team colors every observed technique red and every one their detections caught green; four reds have no green."}, {"type": "term_set", "heading": "Why it helps during response", "terms": [{"term": "Standard communication", "short": "A technique ID means the same thing to every analyst."}, {"term": "Coverage gap analysis", "short": "Shows which observed techniques your detections missed."}, {"term": "Prediction", "short": "Known groups use known technique sets, so you can check for the next step proactively."}]}, {"type": "scenario", "prompt": "Two analysts describe the same behavior differently in their notes. How does ATT&CK help?", "choices": [{"id": "a", "text": "It assigns a CVSS score"}, {"id": "b", "text": "It gives a standard technique name and ID"}, {"id": "c", "text": "It blocks the attacker"}, {"id": "d", "text": "It builds the timeline"}], "answer": "b", "why": "Standardized names remove ambiguity."}, {"type": "scenario", "prompt": "Threat intel links the intruder to a group known to use Kerberoasting after initial access. What should responders do?", "choices": [{"id": "a", "text": "Wait for an alert"}, {"id": "b", "text": "Proactively hunt for Kerberoasting activity"}, {"id": "c", "text": "Close the incident"}, {"id": "d", "text": "Rebuild every server"}], "answer": "b", "why": "ATT&CK''s predictive value lets defenders check for the group''s likely next technique."}, {"type": "callout", "variant": "tip", "text": "In incident response, ATT&CK is about precisely naming what the adversary did."}]'::jsonb where id = 'a3e0ced0-64ed-4c09-94fb-cf8e23935ce1';

-- Incident Response Lifecycle: Preparation, Detection, and Analysis
update lessons set content_blocks = '[{"text": "Incident Response Lifecycle: Preparation, Detection, and Analysis", "type": "title", "overview": "The beginning of the incident response process, from readiness before anything happens through confirming and scoping an actual incident.", "examContext": "The exam frequently tests whether you''d jump ahead or skip a step in the IR lifecycle, know the correct order cold."}, {"type": "diagram", "heading": "The incident response lifecycle", "diagram": {"kind": "flow", "steps": [{"label": "Preparation"}, {"label": "Detection"}, {"label": "Analysis"}, {"label": "Containment"}, {"label": "Eradication"}, {"label": "Recovery"}, {"label": "Post-incident"}]}, "caption": "This lesson covers the first three."}, {"type": "compare", "heading": "Event vs. incident", "columns": ["Event", "Incident"], "rows": [{"label": "Definition", "values": ["Any observable occurrence", "A confirmed violation or imminent threat to security policy"]}, {"label": "Example", "values": ["A failed login", "A confirmed account takeover"]}]}, {"type": "term_set", "heading": "The first three phases", "terms": [{"term": "Preparation", "short": "IR plan, roles, tabletop exercises, tools and access, all before anything happens."}, {"term": "Detection", "short": "An alert, user report or hunt finds a potential event."}, {"term": "Analysis", "short": "Confirm it''s an incident, then scope it, rate severity and start the timeline."}]}, {"type": "scenario", "prompt": "After a messy incident, the review notes nobody knew who could authorize taking servers offline. Which phase failed?", "choices": [{"id": "a", "text": "Detection"}, {"id": "b", "text": "Preparation"}, {"id": "c", "text": "Containment"}, {"id": "d", "text": "Recovery"}], "answer": "b", "why": "Defining roles happens in preparation."}, {"type": "scenario", "prompt": "An alert fires on one host. The analyst checks whether the same account touched other systems and data. Which phase is this?", "choices": [{"id": "a", "text": "Detection"}, {"id": "b", "text": "Analysis (scoping)"}, {"id": "c", "text": "Eradication"}, {"id": "d", "text": "Recovery"}], "answer": "b", "why": "Determining what''s affected is scoping, part of analysis."}, {"type": "callout", "variant": "tip", "text": "Not every event is an incident. Preparation questions ask what should have been done beforehand."}]'::jsonb where id = 'fb2d8d41-db4d-450c-b64a-3fa458f4a48b';

-- Incident Response Lifecycle: Containment, Eradication, and Recovery
update lessons set content_blocks = '[{"text": "Incident Response Lifecycle: Containment, Eradication, and Recovery", "type": "title", "overview": "Once an incident is confirmed and scoped, response moves to limiting damage, removing the adversary''s presence, and safely returning to normal operations.", "examContext": "Know the distinct goal of each phase, a scenario asking ''what''s the NEXT step'' after containment is testing whether you understand eradication comes before recovery."}, {"type": "compare", "heading": "The three response phases", "columns": ["Containment", "Eradication", "Recovery"], "rows": [{"label": "Goal", "values": ["Stop the spread", "Remove the threat", "Return to normal safely"]}, {"label": "Examples", "values": ["Isolate hosts, disable accounts, block C2", "Delete malware, close the hole, remove persistence", "Restore clean systems, heightened monitoring"]}], "cue": ["\"Isolate\"", "\"Remove\"", "\"Restore\""]}, {"type": "compare", "heading": "Short-term vs. long-term containment", "columns": ["Short-term", "Long-term"], "rows": [{"label": "Purpose", "values": ["Immediate isolation", "A durable hold while eradication is planned"]}, {"label": "Example", "values": ["Pull the host off the network", "Move affected servers to a restricted VLAN with extra monitoring"]}]}, {"type": "key_term", "term": "Recovery only after eradication", "definition": "Restoring before the threat is gone invites reinfection. Validate restored systems before relaxing monitoring.", "example": "A server restored from backup is reinfected within hours because the attacker''s backdoor account was never removed."}, {"type": "scenario", "prompt": "Infected hosts have been isolated. What comes next?", "choices": [{"id": "a", "text": "Recovery"}, {"id": "b", "text": "Eradication"}, {"id": "c", "text": "Lessons learned"}, {"id": "d", "text": "Detection"}], "answer": "b", "why": "Remove the threat before restoring."}, {"type": "scenario", "prompt": "A team restores systems from backup while the attacker''s web shell is still on another server. What''s the risk?", "choices": [{"id": "a", "text": "None; backups are clean"}, {"id": "b", "text": "Reinfection, because eradication wasn''t completed"}, {"id": "c", "text": "Loss of chain of custody"}, {"id": "d", "text": "Higher MTTD"}], "answer": "b", "why": "Recovery before eradication is the classic trap."}, {"type": "callout", "variant": "tip", "text": "Contain stops the bleeding, eradicate removes the threat, recover brings it back. Never restore before eradication is confirmed."}]'::jsonb where id = '8104720e-83f5-44f1-a2b9-58b17c0483a2';

-- Playbooks, Triage, and Timeline Construction
update lessons set content_blocks = '[{"text": "Playbooks, Triage, and Timeline Construction", "type": "title", "overview": "The practical techniques that make incident response faster and more consistent: pre-built playbooks, effective triage, and disciplined timeline building.", "examContext": "Expect scenario questions on prioritizing between multiple simultaneous alerts (triage) and questions about what makes a timeline reliable."}, {"type": "term_set", "heading": "Key terms at a glance", "terms": [{"term": "IR playbook", "short": "A decision tree for a common incident type, built before you need it."}, {"term": "Triage", "short": "Prioritizing simultaneous alerts by severity, scope and business impact."}, {"term": "Incident timeline", "short": "Chronological reconstruction from initial access to exfiltration."}]}, {"type": "diagram", "heading": "Triage priority", "diagram": {"kind": "triad", "points": [{"label": "Severity"}, {"label": "Scope"}, {"label": "Business impact"}], "center": "priority"}, "caption": "Not which alert fired first."}, {"type": "term_set", "heading": "Building a reliable timeline", "terms": [{"term": "Log correlation", "short": "Endpoint, network, application and cloud evidence in one sequence."}, {"term": "Time synchronization", "short": "What makes correlation possible."}, {"term": "Gaps", "short": "Missing evidence is noted explicitly, never assumed away."}]}, {"type": "scenario", "prompt": "Three alerts arrive together: a malware hit on an intern''s laptop, suspected exfiltration from the customer database, and a failed login burst on a test VM. Which first?", "choices": [{"id": "a", "text": "The intern''s laptop, since it fired first"}, {"id": "b", "text": "The customer database exfiltration"}, {"id": "c", "text": "The test VM"}, {"id": "d", "text": "All three equally"}], "answer": "b", "why": "Highest severity, widest scope and biggest business impact."}, {"type": "scenario", "prompt": "Firewall logs for a two-hour window are missing. How should the timeline handle it?", "choices": [{"id": "a", "text": "Assume nothing happened then"}, {"id": "b", "text": "Note the gap explicitly"}, {"id": "c", "text": "Fill it with estimates"}, {"id": "d", "text": "Discard the timeline"}], "answer": "b", "why": "Gaps are documented, not assumed away."}, {"type": "callout", "variant": "tip", "text": "Triage by severity, scope and impact together. Document timeline gaps."}]'::jsonb where id = 'e83210fd-971f-493a-879a-985d35696139';

-- Evidence Handling and Chain of Custody
update lessons set content_blocks = '[{"text": "Evidence Handling and Chain of Custody", "type": "title", "overview": "Why the way evidence is collected and documented during an incident matters just as much as what evidence is found.", "examContext": "Expect questions on what breaks chain of custody and what evidence handling principle applies in a described scenario."}, {"type": "key_term", "term": "Chain of custody", "definition": "An unbroken record of who collected evidence, when, how it was stored and who accessed it. Any gap undermines it, especially for legal or HR action.", "example": "A drive sat unlogged on a desk overnight; the defense argues it could have been altered."}, {"type": "diagram", "heading": "Order of volatility", "diagram": {"kind": "ladder", "rungs": [{"label": "CPU registers and cache"}, {"label": "RAM", "note": "Running processes, network connections, keys."}, {"label": "Disk", "note": "Files, swap, temporary data."}, {"label": "Logs and archives", "note": "Backups and remote logs."}], "top": "collect first", "bottom": "collect last"}}, {"type": "term_set", "heading": "Protecting integrity", "terms": [{"term": "Hashing", "short": "Hash at collection to prove later it wasn''t changed."}, {"term": "Write blocker", "short": "Prevents any change to original media during imaging."}, {"term": "Documentation", "short": "Every action logged as it happens, not from memory later."}]}, {"type": "scenario", "prompt": "A compromised server is still running. What should be captured first?", "choices": [{"id": "a", "text": "Disk image"}, {"id": "b", "text": "Memory (RAM)"}, {"id": "c", "text": "Backup tapes"}, {"id": "d", "text": "Firewall archives"}], "answer": "b", "why": "RAM disappears at power off."}, {"type": "scenario", "prompt": "Which proves a disk image hasn''t changed since collection?", "choices": [{"id": "a", "text": "A write blocker"}, {"id": "b", "text": "A matching hash"}, {"id": "c", "text": "A chain of custody form alone"}, {"id": "d", "text": "Encryption"}], "answer": "b", "why": "Matching hashes prove integrity. A write blocker prevents changes during imaging, but the hash is the proof."}, {"type": "callout", "variant": "tip", "text": "RAM before disk, disk before backups. Hash at collection, write-block during imaging, log every touch."}]'::jsonb where id = '06ac9b03-2165-4aae-bd4b-9bde86b5bf2d';

-- Escalation, Root Cause Analysis, and Post-Incident Activity
update lessons set content_blocks = '[{"text": "Escalation, Root Cause Analysis, and Post-Incident Activity", "type": "title", "overview": "Knowing when to bring in more resources during an incident, and the discipline of learning from it afterward so it doesn''t recur.", "examContext": "Post-incident activity is a frequent exam topic, know root cause analysis, lessons learned, and corrective actions as distinct concepts."}, {"type": "key_term", "term": "Escalation", "definition": "Bringing in senior analysts, management, legal, PR or outside responders when an incident exceeds your authority, scope or expertise. Pre-defined criteria keep it from staying at the wrong level.", "example": "Policy says any confirmed data exfiltration escalates to the CISO immediately, so the analyst calls within minutes."}, {"type": "key_term", "term": "Root cause analysis", "definition": "Finds why the incident happened, not just what happened, so the real gap is fixed.", "example": "The symptom was an exploited web server. The root cause was a patch process that skipped servers outside the main domain."}, {"type": "term_set", "heading": "Post-incident activity", "terms": [{"term": "Lessons learned", "short": "A structured, blameless review soon after closure."}, {"term": "Corrective actions", "short": "Tracked follow-ups: patch, update a playbook, add a detection."}, {"term": "After-action report", "short": "The formal record of root cause, timeline and corrective actions."}]}, {"type": "scenario", "prompt": "A breach exploited a vulnerability whose patch had been available for eight months. What''s the root cause?", "choices": [{"id": "a", "text": "The vulnerability"}, {"id": "b", "text": "A gap in patch management"}, {"id": "c", "text": "The attacker"}, {"id": "d", "text": "The firewall"}], "answer": "b", "why": "The flaw is the symptom; the failure to apply an available patch is the root cause."}, {"type": "scenario", "prompt": "What''s the purpose of keeping lessons learned blameless?", "choices": [{"id": "a", "text": "To avoid writing a report"}, {"id": "b", "text": "To get honest input so the process actually improves"}, {"id": "c", "text": "To speed up recovery"}, {"id": "d", "text": "To satisfy regulators"}], "answer": "b", "why": "People share what really happened when they aren''t afraid of blame."}, {"type": "callout", "variant": "tip", "text": "Root cause asks why, not what. Lessons learned should be blameless; corrective actions should be tracked."}]'::jsonb where id = '863553b6-99dd-406c-82f5-7d317ee6347f';

-- Domain 3 Recap: Incident Response and Management
update lessons set content_blocks = '[{"text": "Domain 3 Recap: Incident Response and Management", "type": "title", "overview": "The highest-yield facts from Domain 3, pulled together for a final review before the domain checkpoint.", "examContext": "Read through once, then take the Domain 3 Checkpoint, it uses fresh scenarios, not the same questions from the lesson mini-exams."}, {"type": "term_set", "heading": "Frameworks", "terms": [{"term": "Kill Chain", "short": "Recon, weaponize, deliver, exploit, install, C2, actions."}, {"term": "Diamond Model", "short": "Adversary, capability, infrastructure, victim; pivot between them."}, {"term": "ATT&CK in IR", "short": "Name what happened; find gaps; predict next steps."}]}, {"type": "term_set", "heading": "Lifecycle", "terms": [{"term": "Order", "short": "Preparation, detection, analysis, containment, eradication, recovery, post-incident."}, {"term": "Event / incident", "short": "Any occurrence / confirmed violation."}, {"term": "Contain / eradicate / recover", "short": "Stop spread / remove / restore, only after eradication."}, {"term": "Triage", "short": "Severity, scope and business impact."}]}, {"type": "term_set", "heading": "Evidence and afterward", "terms": [{"term": "Order of volatility", "short": "Registers, RAM, disk, then backups."}, {"term": "Integrity", "short": "Hash, write blocker, document as you go."}, {"term": "Root cause", "short": "Why it happened, not just what."}, {"term": "Lessons learned", "short": "Blameless, with tracked corrective actions."}]}, {"type": "scenario", "prompt": "Which Kill Chain stage involves the malware calling back to the attacker''s server?", "choices": [{"id": "a", "text": "Installation"}, {"id": "b", "text": "Command and control"}, {"id": "c", "text": "Delivery"}, {"id": "d", "text": "Exploitation"}], "answer": "b", "why": "Opening a channel back is C2."}, {"type": "scenario", "prompt": "What should be collected first from a live system?", "choices": [{"id": "a", "text": "Disk"}, {"id": "b", "text": "RAM"}, {"id": "c", "text": "Logs"}, {"id": "d", "text": "Backups"}], "answer": "b", "why": "Most volatile first."}, {"type": "scenario", "prompt": "After containment, what''s next?", "choices": [{"id": "a", "text": "Recovery"}, {"id": "b", "text": "Eradication"}, {"id": "c", "text": "Detection"}, {"id": "d", "text": "Preparation"}], "answer": "b", "why": "Remove the threat before restoring."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Domain Checkpoint: fresh scenarios from every lesson in this domain."}]'::jsonb where id = '2a38db67-3145-4ed5-bf86-39693d7b06fe';

-- Vulnerability Management Reporting
update lessons set content_blocks = '[{"text": "Vulnerability Management Reporting", "type": "title", "overview": "Turning raw scan output into reports that different audiences, technical teams, compliance, and leadership, can actually act on.", "examContext": "Know how to tailor a vulnerability report''s content and framing to its intended audience, and how to communicate why a remediation hasn''t happened yet."}, {"type": "compare", "heading": "Tailor the report to the audience", "columns": ["Needs", "Format"], "rows": [{"label": "Technical teams", "values": ["Affected hosts, CVE IDs, exact fix steps", "Full scan report"]}, {"label": "Compliance and audit", "values": ["Findings mapped to framework requirements", "Compliance findings report"]}, {"label": "Executive leadership", "values": ["Overall posture, trends, top exposures", "Risk scorecard"]}]}, {"type": "key_term", "term": "Remediation inhibitor", "definition": "A documented reason a known vulnerability isn''t fixed yet, communicated openly rather than left unexplained.", "example": "The MRI controller can''t be patched until the vendor certifies the update, so it''s reported as an inhibitor with a segmentation workaround."}, {"type": "key_term", "term": "Compliance findings report", "definition": "Maps results to a framework''s requirements so auditors can see exactly which control is affected.", "example": "\"Finding 14 violates PCI DSS requirement 6.2: critical patches not installed within one month.\""}, {"type": "scenario", "prompt": "The board asks for a vulnerability update. What should they receive?", "choices": [{"id": "a", "text": "The full raw scan export"}, {"id": "b", "text": "A condensed risk scorecard with trends and top exposures"}, {"id": "c", "text": "A list of CVE IDs"}, {"id": "d", "text": "Nessus plugin output"}], "answer": "b", "why": "Leadership needs posture and priorities, not thousands of rows."}, {"type": "scenario", "prompt": "A critical finding has been open for 60 days because the system can''t take downtime until the next plant shutdown. How should this be reported?", "choices": [{"id": "a", "text": "Leave it off the report"}, {"id": "b", "text": "As a documented remediation inhibitor with any compensating controls"}, {"id": "c", "text": "As a false positive"}, {"id": "d", "text": "As remediated"}], "answer": "b", "why": "Inhibitors are reported transparently."}, {"type": "callout", "variant": "tip", "text": "Detail for technicians, framework mapping for auditors, a scorecard for executives."}]'::jsonb where id = '399ec20d-c5f2-4ebe-8907-02d8bcf5a9e8';

-- Vulnerability Metrics and Stakeholder Communication
update lessons set content_blocks = '[{"text": "Vulnerability Metrics and Stakeholder Communication", "type": "title", "overview": "The specific metrics that turn vulnerability management activity into something measurable and communicable to stakeholders.", "examContext": "Expect questions naming a specific metric and asking what it measures, or describing a metric trend and asking what it indicates."}, {"type": "term_set", "heading": "Key metrics", "terms": [{"term": "Trend", "short": "Are open findings, weighted by severity, rising or falling?"}, {"term": "Top risks", "short": "The few findings that deserve stakeholder attention."}, {"term": "Mean time to remediate (MTTR)", "short": "Average time from discovery to fix, by severity."}, {"term": "SLA compliance rate", "short": "Percentage fixed within the target time."}]}, {"type": "key_term", "term": "Remediation SLA", "definition": "An internal target for how fast each severity must be fixed.", "example": "Critical in 15 days, high in 30, medium in 90. This quarter 72% of criticals met the target."}, {"type": "diagram", "heading": "A program falling behind", "diagram": {"kind": "flow", "steps": [{"label": "Open critical count rising"}, {"label": "SLA compliance falling"}, {"label": "MTTR growing"}]}, "caption": "Together these mean the program isn''t keeping pace, no matter how many scans are running."}, {"type": "scenario", "prompt": "Scans run weekly, but open critical findings climb each month and SLA compliance has dropped from 90% to 60%. What does this show?", "choices": [{"id": "a", "text": "The program is healthy because scans are frequent"}, {"id": "b", "text": "The program is falling behind on remediation"}, {"id": "c", "text": "The scanner has too many false positives"}, {"id": "d", "text": "EPSS is miscalculated"}], "answer": "b", "why": "Activity isn''t outcome. Rising criticals and falling SLA compliance mean remediation isn''t keeping up."}, {"type": "scenario", "prompt": "Which metric shows how long, on average, it takes to fix a vulnerability after it''s found?", "choices": [{"id": "a", "text": "SLA compliance rate"}, {"id": "b", "text": "Mean time to remediate"}, {"id": "c", "text": "Alert volume"}, {"id": "d", "text": "MTTD"}], "answer": "b", "why": "MTTR measures discovery to resolution."}, {"type": "callout", "variant": "tip", "text": "Scan counts measure activity. Trends, MTTR and SLA compliance measure results."}]'::jsonb where id = 'e0f19da0-6f19-43e8-90c8-80ef3ca23897';

-- Incident Declaration, Escalation, and Stakeholder Communication
update lessons set content_blocks = '[{"text": "Incident Declaration, Escalation, and Stakeholder Communication", "type": "title", "overview": "The communication side of incident response, formally declaring an incident, notifying the right people, and keeping stakeholders appropriately informed as it unfolds.", "examContext": "Expect scenarios about who needs to be notified and when, and what a communication plan should define ahead of time."}, {"type": "key_term", "term": "Incident declaration", "definition": "The deliberate decision, after analysis, to confirm an incident and activate the response process. It doesn''t happen automatically when an alert fires.", "example": "After confirming the ransomware note and encrypted shares, the incident manager formally declares a severity 1 incident."}, {"type": "term_set", "heading": "Communication plan elements", "terms": [{"term": "Notification triggers", "short": "Which incidents require legal, PR, executives or regulators."}, {"term": "Cadence", "short": "How often updates go out: hourly for major, daily for minor."}, {"term": "Designated spokesperson", "short": "One voice for external communication."}]}, {"type": "key_term", "term": "Need to know", "definition": "Share incident details only with people who have an operational, legal or decision-making reason. Broad sharing can leak details or tip off an insider.", "example": "Suspected insider data theft is shared with HR, legal and the CISO only, not posted in the all-staff channel."}, {"type": "scenario", "prompt": "An analyst sees one suspicious alert and immediately emails the whole company that a breach is underway. What went wrong?", "choices": [{"id": "a", "text": "Nothing; speed matters"}, {"id": "b", "text": "The incident was announced before analysis and declaration, and beyond need to know"}, {"id": "c", "text": "The wrong spokesperson"}, {"id": "d", "text": "The cadence was too slow"}], "answer": "b", "why": "Declaration follows analysis, and communication follows the plan."}, {"type": "scenario", "prompt": "Who should make statements to the press during a major incident?", "choices": [{"id": "a", "text": "Any responder who''s asked"}, {"id": "b", "text": "The designated spokesperson"}, {"id": "c", "text": "The SOC analyst who found it"}, {"id": "d", "text": "Nobody, ever"}], "answer": "b", "why": "One designated voice prevents conflicting statements."}, {"type": "callout", "variant": "tip", "text": "Declaration is a decision, not a reflex. Share on a need-to-know basis, through one spokesperson."}]'::jsonb where id = 'e649db35-ed6c-4afd-816a-fd405ea65612';

-- Incident Response Reporting
update lessons set content_blocks = '[{"text": "Incident Response Reporting", "type": "title", "overview": "How to turn the detailed technical record of an incident into reports that serve different audiences during and after the response.", "examContext": "Know what belongs in an executive summary versus a full technical incident report, and when regulatory notification reporting requirements apply."}, {"type": "compare", "heading": "Three kinds of incident report", "columns": ["Executive summary", "Technical report", "Regulatory notification"], "rows": [{"label": "Audience", "values": ["Leadership", "Analysts, future responders", "Regulators, sometimes individuals"]}, {"label": "Contains", "values": ["Business impact, status, decisions needed", "Timeline, IoCs, ATT&CK mapping, affected assets, actions", "Legally required elements: data types, record counts, discovery date"]}, {"label": "Tone", "values": ["Plain language", "Full technical detail", "Formal, deadline driven"]}]}, {"type": "key_term", "term": "Regulatory breach notification", "definition": "A legally required report when certain data is confirmed compromised, often within a fixed deadline.", "example": "Under GDPR, the supervisory authority must generally be told within 72 hours of becoming aware of a personal data breach."}, {"type": "scenario", "prompt": "An executive summary lists hash values, Sigma rules and ATT&CK IDs. What''s wrong?", "choices": [{"id": "a", "text": "Nothing"}, {"id": "b", "text": "It''s written for the wrong audience"}, {"id": "c", "text": "It''s missing the regulatory deadline"}, {"id": "d", "text": "It''s too short"}], "answer": "b", "why": "Executives need business impact and decisions, not technical indicators."}, {"type": "scenario", "prompt": "Where should the full list of IoCs and the detailed timeline go?", "choices": [{"id": "a", "text": "Executive summary"}, {"id": "b", "text": "Technical incident report"}, {"id": "c", "text": "Press release"}, {"id": "d", "text": "Regulatory notification"}], "answer": "b", "why": "Technical detail belongs in the technical report."}, {"type": "callout", "variant": "tip", "text": "If an executive summary reads like a SIEM alert, it''s for the wrong audience."}]'::jsonb where id = '98d933ab-59dc-4db2-8fee-fedb93c7bf4b';

-- Post-Incident Activity: Root Cause, Lessons Learned, and KPIs
update lessons set content_blocks = '[{"text": "Post-Incident Activity: Root Cause, Lessons Learned, and KPIs", "type": "title", "overview": "How post-incident findings get reported, and the specific metrics used to measure how well a SOC''s detection and response is actually performing.", "examContext": "Know the standard SOC/IR KPIs by name and what each one measures, the exam tests recognition of specific metric definitions."}, {"type": "diagram", "heading": "Where the KPIs fall", "diagram": {"kind": "flow", "steps": [{"label": "Compromise begins"}, {"label": "Detected", "note": "MTTD measures the time up to here."}, {"label": "Response starts", "note": "MTTR measures detection to response."}]}}, {"type": "compare", "heading": "Core SOC KPIs", "columns": ["Measures"], "rows": [{"label": "Mean time to detect (MTTD)", "values": ["How long we were blind"]}, {"label": "Mean time to respond (MTTR)", "values": ["How long we took to act once we saw it"]}, {"label": "Alert volume", "values": ["Total alerts, often alongside the true positive rate"]}, {"label": "False-positive rate", "values": ["Share of alerts that weren''t real; drives alert fatigue"]}], "intro": "This MTTR is different from the vulnerability remediation MTTR earlier in the domain."}, {"type": "key_term", "term": "Reporting improvement", "definition": "Root cause and lessons learned reports show leadership the organization is improving, not just closing tickets.", "example": "A quarterly report shows MTTD fell from 21 days to 4 after new EDR coverage, tied to last year''s lessons learned."}, {"type": "scenario", "prompt": "An attacker was in the network for 90 days before any alert fired. Which KPI does this hurt?", "choices": [{"id": "a", "text": "MTTR"}, {"id": "b", "text": "MTTD"}, {"id": "c", "text": "Alert volume"}, {"id": "d", "text": "SLA compliance"}], "answer": "b", "why": "The delay before detection is MTTD."}, {"type": "scenario", "prompt": "Analysts are ignoring alerts because 95% turn out to be benign. Which metric explains this?", "choices": [{"id": "a", "text": "MTTD"}, {"id": "b", "text": "High false-positive rate"}, {"id": "c", "text": "Low alert volume"}, {"id": "d", "text": "MTTR"}], "answer": "b", "why": "A high false-positive rate causes alert fatigue."}, {"type": "callout", "variant": "tip", "text": "MTTD: how long we were blind. MTTR: how long to act once we saw it."}]'::jsonb where id = '320f3220-7ba3-484a-886b-2056a6d36373';

-- Domain 4 Recap: Reporting and Communication
update lessons set content_blocks = '[{"text": "Domain 4 Recap: Reporting and Communication", "type": "title", "overview": "The highest-yield facts from Domain 4, pulled together for a final review before the domain checkpoint.", "examContext": "Read through once, then take the Domain 4 Checkpoint, it uses fresh scenarios, not the same questions from the lesson mini-exams."}, {"type": "term_set", "heading": "Vulnerability reporting", "terms": [{"term": "Audiences", "short": "Technical detail, compliance mapping, executive scorecard."}, {"term": "Remediation inhibitor", "short": "Documented reason a fix is delayed."}, {"term": "Metrics", "short": "Trend, top risks, MTTR, SLA compliance rate."}]}, {"type": "term_set", "heading": "Incident communication", "terms": [{"term": "Declaration", "short": "A deliberate decision after analysis."}, {"term": "Communication plan", "short": "Triggers, cadence, one spokesperson."}, {"term": "Need to know", "short": "Limit who hears details."}, {"term": "Reports", "short": "Executive summary, technical report, regulatory notification."}]}, {"type": "term_set", "heading": "KPIs", "terms": [{"term": "MTTD", "short": "Time to notice."}, {"term": "MTTR (incident)", "short": "Detection to response."}, {"term": "False-positive rate", "short": "Drives alert fatigue."}]}, {"type": "scenario", "prompt": "Which report maps findings to PCI DSS requirements?", "choices": [{"id": "a", "text": "Risk scorecard"}, {"id": "b", "text": "Compliance findings report"}, {"id": "c", "text": "Executive summary"}, {"id": "d", "text": "After-action report"}], "answer": "b", "why": "Compliance reports map to frameworks."}, {"type": "scenario", "prompt": "Who should receive a short, plain-language summary of business impact and decisions needed?", "choices": [{"id": "a", "text": "SOC analysts"}, {"id": "b", "text": "Executive leadership"}, {"id": "c", "text": "Regulators"}, {"id": "d", "text": "The attacker"}], "answer": "b", "why": "That''s the executive summary."}, {"type": "scenario", "prompt": "A long delay before any alert fired affects which KPI?", "choices": [{"id": "a", "text": "MTTR"}, {"id": "b", "text": "MTTD"}, {"id": "c", "text": "SLA"}, {"id": "d", "text": "EPSS"}], "answer": "b", "why": "Time to detect."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Domain Checkpoint: fresh scenarios from every lesson in this domain."}]'::jsonb where id = 'a2f17b46-0b93-4611-bdac-cfffc81d6b91';
